const TOKEN = "[!#$%&'*+.^_`|~0-9A-Za-z-]+"
const mediaTypeRE = new RegExp(`^[ \\t]*(${TOKEN})/(${TOKEN})[ \\t]*(?=;|$)`)
const tokenRE = new RegExp(`^${TOKEN}$`)
const INVALID_QUOTED = 'invalid quoted string'

/**
 * Parsed representation of a `content-type` header value.
 * A value is "empty" when it is absent or is not a valid
 * `type/subtype` media type (`isValid` distinguishes these cases).
 */
class ContentType {
  #mediaType = ''
  #type = ''
  #subtype = ''
  #parameters = new Map()
  #valid = true

  constructor (header) {
    if (header == null || header === '' || header === 'undefined') {
      return
    }
    header = String(header)

    const match = mediaTypeRE.exec(header)
    if (match === null) {
      this.#valid = false
      return
    }

    this.#type = match[1].toLowerCase()
    this.#subtype = match[2].toLowerCase()
    this.#mediaType = `${this.#type}/${this.#subtype}`
