        // parameter without a value, ignore it
        continue
      }
      pos++ // skip '='

      let value
      if (header[pos] === '"') {
        pos++
        value = ''
        let closed = false
        while (pos < len) {
          const ch = header[pos]
          if (ch === '\\' && pos + 1 < len) {
