'use strict'

const { kTimeoutTimer, kOnAbort, kAbortController } = require('./symbols')

function clearTimeoutTimer (request) {
  const timer = request[kTimeoutTimer]
  if (timer) {
    clearTimeout(timer)
  }
  request[kTimeoutTimer] = null
}

// Creates the AbortController of a request and wires it to the response
// lifecycle: it is aborted on client disconnect, and timer/listeners are
// released as soon as the response is over.
function attachAbortController (request, res) {
  const controller = new AbortController()
  request[kAbortController] = controller
  request[kTimeoutTimer] = null

  const onClose = () => {
    clearTimeoutTimer(request)
    res.removeListener('close', onClose)
    res.removeListener('finish', onClose)
    request[kOnAbort] = null
    if (res.writableFinished === false && !controller.signal.aborted) {
      controller.abort()
    }
  }
  request[kOnAbort] = onClose
  res.on('close', onClose)
  res.on('finish', onClose)
  return controller
}

module.exports = { attachAbortController, clearTimeoutTimer }
E
